    "to": {
      "type": "string",
      "description": "Recipient mailbox id; defaults to your own mailbox."
    }
  },
  "required": [
    "text",
    "delay"
  ]
}

{
  "type": "object",
  "properties": {
    "questions": {
      "type": "array",
      "description": "Questions to ask the user (at least one)",
      "items": {
        "type": "object",
        "properties": {
          "question": {
            "type": "string",
